python3 - <<'PY'
import itertools
words=['secret','secrets','password','archive','solution','challenge','task','file','hidden','private','unlock','extract','sevenzip','7zip','john','security','word','found']
suffix=['','1','12','123','1234','12345','2024','2025','2026','01','007','!','!!','@','#','_file','_file1','_7z','7z']
seps=['','_','-','.']
vals=set()
for w in words:
    forms={w,w.lower(),w.upper(),w.capitalize(),w.replace('e','3').replace('a','@').replace('s','$').replace('i','1')}
    for f in forms:
      for x in suffix: vals.add(f+x)
      for s in seps:
        for v in words: vals.add(f+s+v)
        for x in suffix: vals.add(f+s+x)
for a,b in itertools.product(words,words):
  for s in seps:
    vals.add(a+s+b); vals.add(a.capitalize()+s+b)
with open('/tmp/focused2','w') as f:
  f.write('\n'.join(sorted(vals))+'\n')
print(len(vals))
PY
